config.code:
const body = nodes.fetch_weather.output.body || {};
const imperial = (input.units || 'metric') === 'imperial';
const toF = c => Math.round((c * 9) / 5 + 32);
const toMph = k => Math.round(k * 0.621371);
const convTemp = v => v === null || v === undefined ? null : (imperial ? toF(v) : v);
const convWind = v => v === null || v === undefined ? null : (imperial ? toMph(v) : v);
const cur = body.current || {};
const current_conditions = {
  temperature: convTemp(cur.temperature_2m !== undefined ? cur.temperature_2m : null),
  condition: cur.weather_code !== undefined ? String(cur.weather_code) : null,
  wind_speed: convWind(cur.wind_speed_10m !== undefined ? cur.wind_speed_10m : null),
  precipitation: cur.precipitation !== undefined ? cur.precipitation : null,
  time: cur.time !== undefined ? cur.time : null
};
const d = body.daily || {};
const dates = d.time || [];
const days = dates.slice(0, 4).map((date, i) => ({
  date: date,
  temp_min: convTemp(d.temperature_2m_min && d.temperature_2m_min[i] !== undefined ? d.temperature_2m_min[i] : null),
  temp_max: convTemp(d.temperature_2m_max && d.temperature_2m_max[i] !== undefined ? d.temperature_2m_max[i] : null),
  precipitation_chance: d.precipitation_probability_max && d.precipitation_probability_max[i] !== undefined && d.precipitation_probability_max[i] !== null ? d.precipitation_probability_max[i] : null,
  wind_speed: convWind(d.wind_speed_10m_max && d.wind_speed_10m_max[i] !== undefined ? d.wind_speed_10m_max[i] : null),
  wind_direction: d.wind_direction_10m_dominant && d.wind_direction_10m_dominant[i] !== undefined ? d.wind_direction_10m_dominant[i] : null
}));
const geo = nodes.pick_location.output.match || {};
return {
  current_conditions: current_conditions,
  days: days,
  resolved_location: { name: geo.name || null, country: geo.country || null, admin1: geo.admin1 || null, latitude: geo.latitude || null, longitude: geo.longitude || null, population: geo.population || null }
};

config.prompt:
Write a 1-2 sentence friendly summary for this weather forecast day, including at least one concrete clothing or gear recommendation that is consistent with the numbers (e.g., bring an umbrella if precipitation chance is 50% or more, layer up if it is chilly, sunscreen and light clothes if hot and sunny). Use only the given values; if a value is null, do not mention it.

Day data: {{item | json}}

Units are {{input.units ?? 'metric'}} (metric = °C and km/h, imperial = °F and mph).

config.task:
Compose a short weather briefing from the data below. Structure: one opening line naming the location and summarizing current conditions, then exactly one short sentence (max ~15 words) per day, in order — condense the per-day summaries, do not copy them verbatim. Plain text only: no markdown, no headers, no bold, no bullet symbols. Keep the total under 150 words. If any field in the data is null, state the gap explicitly (e.g., 'wind data unavailable for Tuesday') rather than inventing a value.

LOCATION: {{nodes.assemble.output.location | json}}
CURRENT CONDITIONS: {{nodes.assemble.output.current_conditions | json}}
DAYS: {{nodes.assemble.output.days | json}}
PER-DAY SUMMARIES: {{nodes.assemble.output.summaries | json}}
UNITS: {{nodes.assemble.output.units}}

config.code:
const days = nodes.extract_days.output.days || [];
const summaries = nodes.daily_summaries.output.results || [];
const gaps = [];
if (days.length !== 4) gaps.push('Expected 4 daily entries but got ' + days.length);
const daily_forecast = days.map((d, i) => ({
  ...d,
  summary: summaries[i] !== undefined ? summaries[i] : null
}));
const fields = ['date', 'temp_min', 'temp_max', 'precipitation_chance', 'wind_speed'];
for (const d of daily_forecast) {
  for (const f of fields) {
    if (d[f] === null || d[f] === undefined) gaps.push((d.date || 'unknown date') + ': missing ' + f);
  }
  if (d.summary === null || d.summary === undefined) gaps.push((d.date || 'unknown date') + ': missing summary');
}
return { daily_forecast: daily_forecast, data_gaps: gaps, complete: gaps.length === 0 };

const body = (nodes.geocode.output.body || {});
const results = body.results || [];
const q = (input.city || '').trim();
const base = q.split(',')[0].trim().toLowerCase();
const hasQualifier = q.includes(',');
const matches = results.filter(r => (r.name || '').toLowerCase() === base);
let ambiguous = false;
let options = [];
if (!hasQualifier && matches.length > 1) {
  const regions = new Set(matches.slice(0, 5).map(r => (r.admin1 || '') + '|' + (r.country || '')));
  if (regions.size > 1) {
    ambiguous = true;
    options = matches.slice(0, 5).map(r => ({ label: [r.name, r.admin1, r.country].filter(Boolean).join(', ') }));
  }
}
return { ambiguous: ambiguous, options: options };

const amb = (nodes.check_ambiguity && nodes.check_ambiguity.output) || null;
if (amb && amb.ambiguous) {
  const opts = (amb.options || []).map(o => o.label).join(' | ');
  return { error: "The city name '" + input.city + "' is ambiguous: it matches multiple locations (" + opts + "). Please specify a state, region, or country (e.g., '" + input.city + ", <state or country>') and try again. No forecast was produced." };
}
return { error: "Could not resolve the city '" + input.city + "' to a known location. Please check the spelling or add a country/region (e.g., 'Paris, France') and try again. No forecast was produced." };

const ext = (nodes.extract_days && nodes.extract_days.output) || {};
const val = (nodes.validate && nodes.validate.output) || {};
const brief = (nodes.write_briefing && nodes.write_briefing.output) || {};
const err = (nodes.error_output && nodes.error_output.output) || {};
return {
  current_conditions: ext.current_conditions !== undefined ? ext.current_conditions : null,
  daily_forecast: val.daily_forecast !== undefined ? val.daily_forecast : [],
  briefing_text: brief.text !== undefined ? brief.text : '',
  resolved_location: ext.resolved_location !== undefined ? ext.resolved_location : null,
  data_gaps: val.data_gaps !== undefined ? val.data_gaps : [],
  error: err.error !== undefined ? err.error : ''
};
